import * as THREE from 'three'

// ---------- deterministic noise ----------
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function makeCanvas(size) {
  const c = document.createElement('canvas')
  c.width = size; c.height = size
  return c
}

function toTexture(canvas, repeat = [1, 1], srgb = true) {
  const t = new THREE.CanvasTexture(canvas)
  t.wrapS = t.wrapT = THREE.RepeatWrapping
  t.repeat.set(repeat[0], repeat[1])
  t.anisotropy = 8
  if (srgb) t.colorSpace = THREE.SRGBColorSpace
  t.needsUpdate = true
  return t
}

function addNoise(ctx, size, amount, rand, tint = [0, 0, 0]) {
  const img = ctx.getImageData(0, 0, size, size)
  const d = img.data
  for (let i = 0; i < d.length; i += 4) {
    const n = (rand() - 0.5) * amount
    d[i] = Math.max(0, Math.min(255, d[i] + n + tint[0]))
    d[i + 1] = Math.max(0, Math.min(255, d[i + 1] + n + tint[1]))
    d[i + 2] = Math.max(0, Math.min(255, d[i + 2] + n + tint[2]))
  }
  ctx.putImageData(img, 0, 0)
}

function blotches(ctx, size, count, rand, dark = true) {
  for (let i = 0; i < count; i++) {
    const x = rand() * size, y = rand() * size
    const r = 20 + rand() * size * 0.22
    const g = ctx.createRadialGradient(x, y, 0, x, y, r)
    const a = 0.03 + rand() * 0.1
    g.addColorStop(0, dark ? `rgba(8,9,10,${a})` : `rgba(220,220,205,${a * 0.6})`)
    g.addColorStop(1, 'rgba(0,0,0,0)')
    ctx.fillStyle = g
    ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill()
  }
}

function cracks(ctx, size, count, rand) {
  ctx.strokeStyle = 'rgba(14,15,16,0.5)'
  ctx.lineWidth = 1.2
  for (let i = 0; i < count; i++) {
    let x = rand() * size, y = rand() * size
    ctx.beginPath(); ctx.moveTo(x, y)
    const steps = 8 + (rand() * 14) | 0
    for (let s = 0; s < steps; s++) {
      x += (rand() - 0.5) * 26
      y += (rand() - 0.5) * 26
      ctx.lineTo(x, y)
    }
    ctx.globalAlpha = 0.25 + rand() * 0.4
    ctx.stroke()
    ctx.globalAlpha = 1
  }
}

// ---------- concrete ----------
export function concreteTexture({ size = 512, base = '#6d6d66', repeat = [4, 4], grime = 0.9 } = {}) {
  const c = makeCanvas(size)
  const ctx = c.getContext('2d')
  const rand = mulberry32(1337)
  ctx.fillStyle = base
  ctx.fillRect(0, 0, size, size)
  addNoise(ctx, size, 26, rand)
  blotches(ctx, size, 26 * grime, rand, true)
  blotches(ctx, size, 8 * grime, rand, false)
  cracks(ctx, size, 7 * grime, rand)

  // expansion seams
  ctx.strokeStyle = 'rgba(10,11,12,0.55)'
  ctx.lineWidth = 3
  ctx.beginPath()
  ctx.moveTo(0, size / 2); ctx.lineTo(size, size / 2)
  ctx.moveTo(size / 2, 0); ctx.lineTo(size / 2, size)
  ctx.stroke()
  ctx.strokeStyle = 'rgba(180,180,165,0.06)'
  ctx.lineWidth = 1
  ctx.beginPath()
  ctx.moveTo(0, size / 2 + 3); ctx.lineTo(size, size / 2 + 3)
  ctx.moveTo(size / 2 + 3, 0); ctx.lineTo(size / 2 + 3, size)
  ctx.stroke()

  // tiny aggregate specks
  for (let i = 0; i < 900; i++) {
    ctx.fillStyle = rand() > 0.5 ? 'rgba(255,255,245,0.05)' : 'rgba(0,0,0,0.09)'
    ctx.fillRect(rand() * size, rand() * size, 1.5, 1.5)
  }
  return c
}

export function arenaFloorTexture() {
  const size = 1024
  const c = makeCanvas(size)
  const ctx = c.getContext('2d')
  const rand = mulberry32(99)
  ctx.drawImage(concreteTexture({ size: 512, base: '#5e5f5a', grime: 1.2 }), 0, 0, size, size)
  addNoise(ctx, size, 16, rand)

  // large slabs
  ctx.strokeStyle = 'rgba(9,10,11,0.55)'
  ctx.lineWidth = 5
  for (let i = 1; i < 4; i++) {
    ctx.beginPath(); ctx.moveTo(i * size / 4, 0); ctx.lineTo(i * size / 4, size); ctx.stroke()
    ctx.beginPath(); ctx.moveTo(0, i * size / 4); ctx.lineTo(size, i * size / 4); ctx.stroke()
  }
  ctx.strokeStyle = 'rgba(190,190,175,0.05)'
  ctx.lineWidth = 1.5
  for (let i = 1; i < 4; i++) {
    ctx.beginPath(); ctx.moveTo(i * size / 4 + 5, 0); ctx.lineTo(i * size / 4 + 5, size); ctx.stroke()
    ctx.beginPath(); ctx.moveTo(0, i * size / 4 + 5); ctx.lineTo(size, i * size / 4 + 5); ctx.stroke()
  }

  // painted landing circle
  const cx = size / 2, cy = size / 2
  ctx.save()
  ctx.strokeStyle = 'rgba(230,225,205,0.20)'
  ctx.lineWidth = 9
  ctx.beginPath(); ctx.arc(cx, cy, 300, 0, Math.PI * 2); ctx.stroke()
  ctx.lineWidth = 3
  ctx.setLineDash([26, 20])
  ctx.beginPath(); ctx.arc(cx, cy, 330, 0, Math.PI * 2); ctx.stroke()
  ctx.setLineDash([])
  ctx.strokeStyle = 'rgba(255,120,40,0.22)'
  ctx.lineWidth = 12
  ctx.beginPath(); ctx.arc(cx, cy, 268, 0, Math.PI * 2); ctx.stroke()

  // hazard chevrons near edges
  ctx.globalAlpha = 0.16
  for (let i = 0; i < 4; i++) {
    ctx.save()
    ctx.translate(cx, cy)
    ctx.rotate(i * Math.PI / 2)
    for (let s = 0; s < 5; s++) {
      ctx.fillStyle = s % 2 ? '#e8b33c' : '#1a1b1c'
      ctx.fillRect(-250 + s * 22, -438, 22, 26)
    }
    ctx.restore()
  }
  ctx.globalAlpha = 1

  // stenciled sector mark
  ctx.save()
  ctx.translate(cx, cy + 420)
  ctx.fillStyle = 'rgba(220,218,200,0.16)'
  ctx.font = '700 34px "Arial Narrow", Arial, sans-serif'
  ctx.textAlign = 'center'
  ctx.letterSpacing = '10px'
  ctx.fillText('BLACKSITE 07', 0, 0)
  ctx.restore()

  // grime + tire scuffs
  blotches(ctx, size, 40, rand, true)
  ctx.strokeStyle = 'rgba(10,10,10,0.16)'
  for (let i = 0; i < 26; i++) {
    ctx.lineWidth = 1 + rand() * 3
    const x = rand() * size, y = rand() * size
    ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + (rand() - 0.5) * 160, y + (rand() - 0.5) * 160); ctx.stroke()
  }
  return toTexture(c, [1, 1])
}

// ---------- painted metal panels ----------
export function panelTexture({ base = '#3f464e', repeat = [3, 2], accent = '#5a626b' } = {}) {
  const size = 512
  const c = makeCanvas(size)
  const ctx = c.getContext('2d')
  const rand = mulberry32(4242)
  ctx.fillStyle = base
  ctx.fillRect(0, 0, size, size)
  addNoise(ctx, size, 14, rand)

  // brushed streaks
  for (let i = 0; i < 420; i++) {
    ctx.strokeStyle = rand() > 0.5 ? 'rgba(255,255,255,0.025)' : 'rgba(0,0,0,0.05)'
    ctx.lineWidth = 1
    const y = rand() * size
    ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(size, y + (rand() - 0.5) * 4); ctx.stroke()
  }

  // panels
  const pw = size / 2, ph = size / 4
  for (let py = 0; py < 4; py++) {
    for (let px = 0; px < 2; px++) {
      const x = px * pw, y = py * ph
      ctx.strokeStyle = 'rgba(7,8,9,0.7)'
      ctx.lineWidth = 4
      ctx.strokeRect(x + 3, y + 3, pw - 6, ph - 6)
      ctx.strokeStyle = 'rgba(255,255,255,0.05)'
      ctx.lineWidth = 1
      ctx.strokeRect(x + 7, y + 7, pw - 14, ph - 14)
      // rivets
      ctx.fillStyle = 'rgba(160,168,175,0.28)'
      for (const [rx, ry] of [[12, 12], [pw - 12, 12], [12, ph - 12], [pw - 12, ph - 12]]) {
        ctx.beginPath(); ctx.arc(x + rx, y + ry, 2.6, 0, Math.PI * 2); ctx.fill()
      }
      // subtle scuffs
      ctx.globalAlpha = 0.08
      ctx.fillStyle = accent
      ctx.fillRect(x + 20, y + ph * 0.55, pw - 40, 3)
      ctx.globalAlpha = 1
    }
  }
  blotches(ctx, size, 18, rand, true)
  cracks(ctx, size, 3, rand)
  return toTexture(c, repeat)
}

export function containerTexture(tint = '#3d4a52') {
  const size = 512
  const c = makeCanvas(size)
  const ctx = c.getContext('2d')
  const rand = mulberry32(7)
  ctx.fillStyle = tint
  ctx.fillRect(0, 0, size, size)
  // corrugation
  for (let x = 0; x < size; x += 32) {
    const g = ctx.createLinearGradient(x, 0, x + 32, 0)
    g.addColorStop(0, 'rgba(0,0,0,0.28)')
    g.addColorStop(0.35, 'rgba(255,255,255,0.06)')
    g.addColorStop(0.6, 'rgba(255,255,255,0.02)')
    g.addColorStop(1, 'rgba(0,0,0,0.3)')
    ctx.fillStyle = g
    ctx.fillRect(x, 0, 32, size)
  }
  addNoise(ctx, size, 18, rand)
  // frame
  ctx.strokeStyle = 'rgba(8,9,10,0.75)'
  ctx.lineWidth = 10
  ctx.strokeRect(5, 5, size - 10, size - 10)
  ctx.strokeStyle = 'rgba(0,0,0,0.5)'
  ctx.lineWidth = 5
  ctx.strokeRect(16, 16, size - 32, size - 32)
  // rust
  for (let i = 0; i < 26; i++) {
    const x = rand() * size, y = rand() * size, r = 4 + rand() * 22
    const g = ctx.createRadialGradient(x, y, 0, x, y, r)
    g.addColorStop(0, 'rgba(96,54,30,0.35)')
    g.addColorStop(1, 'rgba(96,54,30,0)')
    ctx.fillStyle = g
    ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill()
  }
  blotches(ctx, size, 16, rand, true)
  // stencil
  ctx.save()
  ctx.translate(size / 2, size / 2)
  ctx.rotate(-Math.PI / 2)
  ctx.fillStyle = 'rgba(225,225,210,0.15)'
  ctx.font = '700 40px "Arial Narrow", Arial, sans-serif'
  ctx.textAlign = 'center'
  ctx.letterSpacing = '8px'
  ctx.fillText('BLACKSITE', 0, 10)
  ctx.restore()
  return toTexture(c, [1, 1])
}

export function crateTexture() {
  const size = 512
  const c = makeCanvas(size)
  const ctx = c.getContext('2d')
  const rand = mulberry32(21)
  ctx.fillStyle = '#4a4f45'
  ctx.fillRect(0, 0, size, size)
  addNoise(ctx, size, 22, rand)
  ctx.strokeStyle = 'rgba(8,9,9,0.8)'
  ctx.lineWidth = 16
  ctx.strokeRect(8, 8, size - 16, size - 16)
  ctx.strokeStyle = 'rgba(255,255,255,0.06)'
  ctx.lineWidth = 3
  ctx.strokeRect(28, 28, size - 56, size - 56)
  // diagonal brace
  ctx.strokeStyle = 'rgba(10,11,11,0.55)'
  ctx.lineWidth = 20
  ctx.beginPath(); ctx.moveTo(40, 40); ctx.lineTo(size - 40, size - 40); ctx.stroke()
  // label
  ctx.fillStyle = 'rgba(230,225,200,0.28)'
  ctx.font = '700 44px "Arial Narrow", Arial, sans-serif'
  ctx.textAlign = 'center'
  ctx.fillText('MK-7', size / 2, size / 2 - 18)
  ctx.font = '500 24px monospace'
  ctx.fillText('7.62 // 840 RDS', size / 2, size / 2 + 26)
  blotches(ctx, size, 14, rand, true)
  return toTexture(c, [1, 1])
}

export function hazardTexture() {
  const size = 256
  const c = makeCanvas(size)
  const ctx = c.getContext('2d')
  ctx.fillStyle = '#d9a52e'
  ctx.fillRect(0, 0, size, size)
  ctx.strokeStyle = '#161616'
  ctx.lineWidth = 34
  for (let i = -size; i < size * 2; i += 68) {
    ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i + size, size); ctx.stroke()
  }
  const rand = mulberry32(5)
  addNoise(ctx, size, 26, rand)
  blotches(ctx, size, 12, rand, true)
  return toTexture(c, [2, 1])
}

// ---------- glow sprites ----------
export function glowTexture(inner = 'rgba(255,255,255,1)', mid = 'rgba(255,190,120,0.55)') {
  const size = 128
  const c = makeCanvas(size)
  const ctx = c.getContext('2d')
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2)
  g.addColorStop(0, inner)
  g.addColorStop(0.25, mid)
  g.addColorStop(1, 'rgba(0,0,0,0)')
  ctx.fillStyle = g
  ctx.fillRect(0, 0, size, size)
  return toTexture(c, [1, 1])
}

export function sparkTexture() {
  const size = 64
  const c = makeCanvas(size)
  const ctx = c.getContext('2d')
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2)
  g.addColorStop(0, 'rgba(255,255,255,1)')
  g.addColorStop(0.3, 'rgba(255,220,160,0.9)')
  g.addColorStop(1, 'rgba(255,120,20,0)')
  ctx.fillStyle = g
  ctx.fillRect(0, 0, size, size)
  return toTexture(c, [1, 1])
}

export function smokeTexture() {
  const size = 128
  const c = makeCanvas(size)
  const ctx = c.getContext('2d')
  const rand = mulberry32(31)
  const g = ctx.createRadialGradient(size / 2, size / 2, 4, size / 2, size / 2, size / 2)
  g.addColorStop(0, 'rgba(120,124,130,0.5)')
  g.addColorStop(0.5, 'rgba(90,94,100,0.22)')
  g.addColorStop(1, 'rgba(60,64,70,0)')
  ctx.fillStyle = g
  ctx.fillRect(0, 0, size, size)
  for (let i = 0; i < 40; i++) {
    const x = rand() * size, y = rand() * size, r = 6 + rand() * 20
    const gg = ctx.createRadialGradient(x, y, 0, x, y, r)
    gg.addColorStop(0, 'rgba(150,154,160,0.06)')
    gg.addColorStop(1, 'rgba(150,154,160,0)')
    ctx.fillStyle = gg
    ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill()
  }
  return toTexture(c, [1, 1])
}

export function bulletHoleTexture() {
  const size = 64
  const c = makeCanvas(size)
  const ctx = c.getContext('2d')
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2)
  g.addColorStop(0, 'rgba(5,5,6,0.95)')
  g.addColorStop(0.45, 'rgba(18,18,20,0.8)')
  g.addColorStop(0.75, 'rgba(60,60,60,0.25)')
  g.addColorStop(1, 'rgba(0,0,0,0)')
  ctx.fillStyle = g
  ctx.fillRect(0, 0, size, size)
  return toTexture(c, [1, 1])
}

export function signTexture(text = 'SECTOR 07', sub = 'AUTHORIZED PERSONNEL ONLY') {
  const w = 512, h = 192
  const c = document.createElement('canvas')
  c.width = w; c.height = h
  const ctx = c.getContext('2d')
  ctx.fillStyle = '#101317'
  ctx.fillRect(0, 0, w, h)
  ctx.strokeStyle = 'rgba(255,122,26,0.8)'
  ctx.lineWidth = 4
  ctx.strokeRect(8, 8, w - 16, h - 16)
  ctx.fillStyle = 'rgba(255,138,48,0.95)'
  ctx.font = '700 62px "Arial Narrow", Arial, sans-serif'
  ctx.textAlign = 'center'
  ctx.letterSpacing = '6px'
  ctx.fillText(text, w / 2, 92)
  ctx.fillStyle = 'rgba(190,198,205,0.55)'
  ctx.font = '500 22px monospace'
  ctx.letterSpacing = '4px'
  ctx.fillText(sub, w / 2, 136)
  ctx.fillStyle = 'rgba(255,122,26,0.9)'
  for (let i = 0; i < 3; i++) ctx.fillRect(w / 2 - 90 + i * 70, 154, 50, 6)
  return toTexture(c, [1, 1])
}

export function windowTexture() {
  const size = 256
  const c = makeCanvas(size)
  const ctx = c.getContext('2d')
  ctx.fillStyle = '#05070a'
  ctx.fillRect(0, 0, size, size)
  const rand = mulberry32(88)
  for (let y = 0; y < 16; y++) {
    for (let x = 0; x < 10; x++) {
      if (rand() > 0.55) {
        const warm = rand() > 0.3
        ctx.fillStyle = warm
          ? `rgba(255,${150 + rand() * 60 | 0},${70 + rand() * 50 | 0},${0.25 + rand() * 0.55})`
          : `rgba(${110 + rand() * 40 | 0},${180 + rand() * 50 | 0},255,${0.2 + rand() * 0.4})`
        ctx.fillRect(x * 26 + 4, y * 16 + 3, 14 + rand() * 6, 7)
      }
    }
  }
  return toTexture(c, [1, 1])
}

import * as THREE from 'three'
import {
  arenaFloorTexture, panelTexture, containerTexture, crateTexture,
  hazardTexture, glowTexture, smokeTexture, signTexture, windowTexture, concreteTexture
} from './textures.js'

const UP = new THREE.Vector3(0, 1, 0)

function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

export function resolveCircle(pos, radius, colliders, feetY = 0) {
  for (const c of colliders) {
    if (c.top <= feetY + 0.35) continue
    const cx = Math.max(c.minX, Math.min(pos.x, c.maxX))
    const cz = Math.max(c.minZ, Math.min(pos.z, c.maxZ))
    let dx = pos.x - cx
    let dz = pos.z - cz
    const d2 = dx * dx + dz * dz
    if (d2 < radius * radius) {
      if (d2 > 1e-6) {
        const d = Math.sqrt(d2)
        pos.x = cx + (dx / d) * radius
        pos.z = cz + (dz / d) * radius
      } else {
        const left = pos.x - c.minX, right = c.maxX - pos.x
        const near = pos.z - c.minZ, far = c.maxZ - pos.z
        const m = Math.min(left, right, near, far)
        if (m === left) pos.x = c.minX - radius
        else if (m === right) pos.x = c.maxX + radius
        else if (m === near) pos.z = c.minZ - radius
        else pos.z = c.maxZ + radius
      }
    }
  }
}

export class World {
  constructor(scene, renderer) {
    this.scene = scene
    this.renderer = renderer
    this.colliders = []
    this.solids = []
    this.lights = []
    this.flickers = []
    this.dust = null
    this.time = 0
    this.spawnPoints = [
      new THREE.Vector3(-25, 0, -25), new THREE.Vector3(25, 0, -25),
      new THREE.Vector3(-25, 0, 25), new THREE.Vector3(25, 0, 25),
      new THREE.Vector3(0, 0, -27), new THREE.Vector3(0, 0, 27),
      new THREE.Vector3(-27, 0, 0), new THREE.Vector3(27, 0, 0),
      new THREE.Vector3(-12, 0, -24), new THREE.Vector3(13, 0, 24)
    ]
    this.raycaster = new THREE.Raycaster()
    this._build()
  }

  _build() {
    const rand = mulberry32(2024)
    this.scene.fog = new THREE.FogExp2(0x070b11, 0.0135)
    this.scene.background = new THREE.Color(0x05070b)

    this._sky()
    this._ground()
    this._walls()
    this._catwalk()
    this._props(rand)
    this._lighting()
    this._dust()
    this._skyline(rand)
  }

  _sky() {
    const geo = new THREE.SphereGeometry(150, 32, 20)
    const mat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      uniforms: { uTime: { value: 0 } },
      vertexShader: /* glsl */`
        varying vec3 vDir;
        void main() {
          vDir = normalize(position);
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: /* glsl */`
        varying vec3 vDir;
        uniform float uTime;
        float hash(vec3 p) {
          p = fract(p * 0.3183099 + 0.1);
          p *= 17.0;
          return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
        }
        void main() {
          float h = clamp(vDir.y * 1.4, -0.2, 1.0);
          vec3 horizon = vec3(0.055, 0.075, 0.105);
          vec3 mid = vec3(0.022, 0.032, 0.052);
          vec3 zenith = vec3(0.004, 0.008, 0.018);
          vec3 col = mix(horizon, mid, smoothstep(0.0, 0.35, h));
          col = mix(col, zenith, smoothstep(0.3, 1.0, h));
          // low warm haze
          col += vec3(0.16, 0.07, 0.025) * pow(max(0.0, 1.0 - abs(vDir.y) * 5.0), 3.0) * 0.5;
          // stars
          vec3 sp = floor(vDir * 260.0);
          float star = hash(sp);
          float tw = 0.6 + 0.4 * sin(uTime * 1.3 + star * 60.0);
          col += vec3(0.65, 0.75, 1.0) * smoothstep(0.9975, 1.0, star) * smoothstep(0.06, 0.3, vDir.y) * tw;
          gl_FragColor = vec4(col, 1.0);
        }
      `
    })
    this.skyMat = mat
    const sky = new THREE.Mesh(geo, mat)
    sky.frustumCulled = false
    this.scene.add(sky)

    // moon
    const moonGlow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTexture('rgba(235,242,255,1)', 'rgba(170,195,255,0.5)'),
      color: 0xcfe0ff, transparent: true, opacity: 0.75,
      blending: THREE.AdditiveBlending, depthWrite: false
    }))
    moonGlow.scale.set(30, 30, 1)
    moonGlow.position.set(-52, 46, -104)
    this.scene.add(moonGlow)
    const moon = new THREE.Mesh(
      new THREE.CircleGeometry(3.4, 40),
      new THREE.MeshBasicMaterial({ color: 0xe8eeff, fog: false })
    )
    moon.position.copy(moonGlow.position).add(new THREE.Vector3(2, 1, 2))
    moon.lookAt(0, 2, 0)
    this.scene.add(moon)
  }

  _ground() {
    const floorTex = arenaFloorTexture()
    const mat = new THREE.MeshStandardMaterial({
      map: floorTex, bumpMap: floorTex, bumpScale: 0.055,
      roughness: 0.9, metalness: 0.06, color: 0xb9bab2
    })
    const geo = new THREE.PlaneGeometry(80, 80, 1, 1)
    const floor = new THREE.Mesh(geo, mat)
    floor.rotation.x = -Math.PI / 2
    floor.receiveShadow = true
    this.scene.add(floor)
    this.floor = floor
    this.solids.push(floor)

    // surrounding darker apron
    const apron = new THREE.Mesh(
      new THREE.RingGeometry(40, 120, 48),
      new THREE.MeshStandardMaterial({ color: 0x0a0d12, roughness: 1 })
    )
    apron.rotation.x = -Math.PI / 2
    apron.position.y = -0.02
    this.scene.add(apron)
  }

  _walls() {
    const tex = panelTexture({ base: '#3b424a', repeat: [5, 2] })
    const mat = new THREE.MeshStandardMaterial({ map: tex, roughness: 0.72, metalness: 0.55, color: 0x9fa8b2 })
    const capMat = new THREE.MeshStandardMaterial({ color: 0x23282e, roughness: 0.6, metalness: 0.7 })
    const stripMat = new THREE.MeshStandardMaterial({ color: 0x120a04, emissive: 0xff6a14, emissiveIntensity: 2.2, roughness: 0.4 })
    const cyanMat = new THREE.MeshStandardMaterial({ color: 0x04121a, emissive: 0x33c8ff, emissiveIntensity: 1.6, roughness: 0.4 })

    const H = 9, T = 1.4, S = 30.7
    const defs = [
      { w: S * 2, x: 0, z: -S, ry: 0 },
      { w: S * 2, x: 0, z: S, ry: 0 },
      { w: S * 2, x: -S, z: 0, ry: Math.PI / 2 },
      { w: S * 2, x: S, z: 0, ry: Math.PI / 2 }
    ]
    for (const d of defs) {
      const wall = new THREE.Mesh(new THREE.BoxGeometry(d.w, H, T), mat)
      wall.position.set(d.x, H / 2, d.z)
      wall.rotation.y = d.ry
      wall.castShadow = true
      wall.receiveShadow = true
      this.scene.add(wall)
      this.solids.push(wall)
      this._collider(d.x, d.z, d.w, T, d.ry, H)

      // top cap
      const cap = new THREE.Mesh(new THREE.BoxGeometry(d.w, 0.28, T + 0.5), capMat)
      cap.position.set(d.x, H + 0.1, d.z)
      cap.rotation.y = d.ry
      this.scene.add(cap)

      // emissive strips
      for (const y of [2.5, 6.6]) {
        const strip = new THREE.Mesh(new THREE.BoxGeometry(d.w - 1, 0.09, 0.06), y > 4 ? cyanMat : stripMat)
        strip.position.set(d.x, y, d.z)
        strip.rotation.y = d.ry
        strip.translateZ(T / 2 + 0.035)
        this.scene.add(strip)
      }
    }

    // inner corner braces
    for (const sx of [-1, 1]) {
      for (const sz of [-1, 1]) {
        const brace = new THREE.Mesh(new THREE.BoxGeometry(0.7, 9, 0.7), capMat)
        brace.position.set(sx * 29.2, 4.5, sz * 29.2)
        brace.castShadow = true
        this.scene.add(brace)
        this._collider(sx * 29.2, sz * 29.2, 0.7, 0.7, 0, 9)
      }
    }

    // wall signage
    const sign = new THREE.Mesh(
      new THREE.PlaneGeometry(7.2, 2.7),
      new THREE.MeshBasicMaterial({ map: signTexture(), transparent: true, color: 0xffffff })
    )
    sign.position.set(0, 5.2, -29.9)
    this.scene.add(sign)
    const sign2 = sign.clone()
    sign2.position.set(-29.9, 5.2, 6)
    sign2.rotation.y = Math.PI / 2
    this.scene.add(sign2)

    // pipes along the east wall
    const pipeMat = new THREE.MeshStandardMaterial({ color: 0x4a3b2e, metalness: 0.85, roughness: 0.5 })
    for (let i = 0; i < 3; i++) {
      const pipe = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.16, 26, 10), pipeMat)
      pipe.rotation.z = Math.PI / 2
      pipe.position.set(18 + i * 0.01, 7.4 - i * 0.42, 28.4)
      pipe.castShadow = true
      this.scene.add(pipe)
    }
  }

  _catwalk() {
    const metal = new THREE.MeshStandardMaterial({ color: 0x33383e, metalness: 0.8, roughness: 0.55 })
    const grate = new THREE.MeshStandardMaterial({ color: 0x2b3036, metalness: 0.7, roughness: 0.7 })
    const deck = new THREE.Mesh(new THREE.BoxGeometry(30, 0.22, 2.6), grate)
    deck.position.set(-2, 4.35, -28.2)
    deck.castShadow = true
    deck.receiveShadow = true
    this.scene.add(deck)
    this._collider(-2, -28.2, 30, 2.6, 0, 4.46)

    const railMat = metal
    for (let x = -16; x <= 12; x += 2.4) {
      const post = new THREE.Mesh(new THREE.BoxGeometry(0.09, 1.15, 0.09), railMat)
      post.position.set(x, 5.05, -27.0)
      this.scene.add(post)
    }
    for (const y of [4.9, 5.55]) {
      const bar = new THREE.Mesh(new THREE.BoxGeometry(30, 0.06, 0.06), railMat)
      bar.position.set(-2, y, -27.0)
      this.scene.add(bar)
    }
    // ladder
    for (let i = 0; i < 8; i++) {
      const rung = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.05, 0.05), railMat)
      rung.position.set(13.4, 0.6 + i * 0.5, -29.4)
      this.scene.add(rung)
    }
    for (const x of [13.05, 13.75]) {
      const rail = new THREE.Mesh(new THREE.BoxGeometry(0.05, 4.4, 0.05), railMat)
      rail.position.set(x, 2.2, -29.4)
      this.scene.add(rail)
    }

    // stair light
    const l = new THREE.PointLight(0x77ccff, 14, 12, 2)
    l.position.set(8, 5.2, -27)
    this.scene.add(l)
    this.lights.push(l)
  }

  _props(rand) {
    const containerColors = ['#3c4b53', '#4b3d35', '#39464a', '#463f3a']
    const containerTex = containerColors.map(c => containerTexture(c))
    const containerMats = containerTex.map(t => new THREE.MeshStandardMaterial({
      map: t, roughness: 0.72, metalness: 0.55, color: 0xaab0b4
    }))
    const trimMat = new THREE.MeshStandardMaterial({ color: 0x1d2125, metalness: 0.8, roughness: 0.5 })

    const containers = [
      { x: -17, z: -10, ry: 0.22, i: 0, stack: true },
      { x: 14.5, z: -16.5, ry: -0.14, i: 1 },
      { x: -14, z: 15.5, ry: -0.5, i: 2 },
      { x: 17, z: 11.5, ry: 0.08, i: 3 },
      { x: 7, z: 21.5, ry: 1.52, i: 1 }
    ]
    const cw = 6.2, ch = 2.65, cd = 2.5
    for (const c of containers) {
      const m = new THREE.Mesh(new THREE.BoxGeometry(cw, ch, cd), containerMats[c.i])
      m.position.set(c.x, ch / 2, c.z)
      m.rotation.y = c.ry
      m.castShadow = true
      m.receiveShadow = true
      this.scene.add(m)
      this.solids.push(m)
      this._collider(c.x, c.z, cw, cd, c.ry, ch)

      // door end frame
      for (const s of [-1, 1]) {
        const edge = new THREE.Mesh(new THREE.BoxGeometry(0.12, ch, 0.12), trimMat)
        edge.position.set(s * (cw / 2 - 0.06), ch / 2, cd / 2 + 0.03)
        edge.rotation.y = c.ry
        edge.position.applyAxisAngle(UP, c.ry)
        edge.position.add(new THREE.Vector3(c.x, 0, c.z))
        this.scene.add(edge)
      }

      if (c.stack) {
        const top = new THREE.Mesh(new THREE.BoxGeometry(cw * 0.92, ch, cd), containerMats[(c.i + 2) % 4])
        top.position.set(c.x + 0.4, ch * 1.5 + 0.02, c.z - 0.2)
        top.rotation.y = 0.06
        top.castShadow = true
        top.receiveShadow = true
        this.scene.add(top)
        this.solids.push(top)
        this._collider(c.x + 0.4, c.z - 0.2, cw * 0.92, cd, 0.06, ch * 2)
      }

      // hazard placard
      const plac = new THREE.Mesh(
        new THREE.PlaneGeometry(0.9, 0.6),
        new THREE.MeshStandardMaterial({ map: hazardTexture(), emissive: 0x2a1c00, emissiveIntensity: 0.4, roughness: 0.8 })
      )
      plac.position.set(c.x, 1.7, c.z)
      plac.rotation.y = c.ry
      plac.translateZ(cd / 2 + 0.02)
      this.scene.add(plac)
    }

    // crates
    const crateTex = crateTexture()
    const crateMat = new THREE.MeshStandardMaterial({ map: crateTex, roughness: 0.85, metalness: 0.15 })
    const crateGroups = [
      [-23, -1.5], [10.5, 19.5], [21, -4], [-6.5, -21.5], [4.5, 7.5], [-22, 8]
    ]
    for (const [gx, gz] of crateGroups) {
      const n = 2 + (rand() * 3 | 0)
      for (let i = 0; i < n; i++) {
        const s = 1.15 + rand() * 0.3
        const cx = gx + (rand() - 0.5) * 1.8
        const cz = gz + (rand() - 0.5) * 1.8
        const level = i % 2
        const crate = new THREE.Mesh(new THREE.BoxGeometry(s, s, s), crateMat)
        crate.position.set(cx, s / 2 + level * s, cz)
        crate.rotation.y = (rand() - 0.5) * 0.7
        crate.castShadow = true
        crate.receiveShadow = true
        this.scene.add(crate)
        this.solids.push(crate)
        this._collider(cx, cz, s, s, crate.rotation.y, s * (level + 1))
      }
    }

    // barrels
    const barrelMat = new THREE.MeshStandardMaterial({ color: 0x4a4034, metalness: 0.8, roughness: 0.55 })
    const ringMat = new THREE.MeshStandardMaterial({ color: 0x151719, metalness: 0.6, roughness: 0.6 })
    const hazardMat = new THREE.MeshStandardMaterial({ map: hazardTexture(), roughness: 0.8 })
    const barrelSpots = [[-19, -5], [-18, -3.4], [16, 17], [17.4, 17.4], [22, 6], [-9, 22], [8, -23]]
    for (const [bx, bz] of barrelSpots) {
      const g = new THREE.Group()
      const b = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.42, 1.12, 16), barrelMat)
      b.castShadow = true; b.receiveShadow = true
      g.add(b)
      for (const y of [-0.42, 0.42]) {
        const r = new THREE.Mesh(new THREE.TorusGeometry(0.43, 0.035, 6, 18), ringMat)
        r.rotation.x = Math.PI / 2
        r.position.y = y
        g.add(r)
      }
      const band = new THREE.Mesh(new THREE.CylinderGeometry(0.425, 0.425, 0.22, 16), hazardMat)
      band.position.y = 0.05
      g.add(band)
      g.position.set(bx, 0.56, bz)
      this.scene.add(g)
      this._collider(bx, bz, 0.9, 0.9, 0, 1.12)
    }

    // pillars
    const pillarTex = concreteTexture({ base: '#5a5a54', repeat: [1, 3] })
    const pillarMat = new THREE.MeshStandardMaterial({ map: pillarTex, roughness: 0.9, color: 0x9a9a92 })
    for (const sx of [-1, 1]) {
      for (const sz of [-1, 1]) {
        const p = new THREE.Mesh(new THREE.BoxGeometry(1.5, 9, 1.5), pillarMat)
        p.position.set(sx * 23, 4.5, sz * 23)
        p.castShadow = true; p.receiveShadow = true
        this.scene.add(p)
        this.solids.push(p)
        this._collider(sx * 23, sz * 23, 1.5, 1.5, 0, 9)
        const band = new THREE.Mesh(new THREE.BoxGeometry(1.62, 0.18, 1.62), hazardMat)
        band.position.set(sx * 23, 1.2, sz * 23)
        this.scene.add(band)
      }
    }

    // central beacon
    const beaconBase = new THREE.Mesh(
      new THREE.CylinderGeometry(1.15, 1.35, 0.7, 24),
      new THREE.MeshStandardMaterial({ color: 0x24292f, metalness: 0.8, roughness: 0.45 })
    )
    beaconBase.position.y = 0.35
    beaconBase.castShadow = true; beaconBase.receiveShadow = true
    this.scene.add(beaconBase)
    this._collider(0, 0, 2.4, 2.4, 0, 0.7)
    const beaconCore = new THREE.Mesh(
      new THREE.CylinderGeometry(0.16, 0.22, 1.6, 12),
      new THREE.MeshStandardMaterial({ color: 0x0a2530, emissive: 0x38d8ff, emissiveIntensity: 3.5 })
    )
    beaconCore.position.y = 1.5
    this.scene.add(beaconCore)
    const beam = new THREE.Mesh(
      new THREE.CylinderGeometry(0.3, 0.9, 9, 16, 1, true),
      new THREE.MeshBasicMaterial({ color: 0x2ec8ff, transparent: true, opacity: 0.06, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide })
    )
    beam.position.y = 5.2
    this.scene.add(beam)
    this.beacon = beaconCore
    this.beaconBeam = beam

    // ground debris
    const debrisMat = new THREE.MeshStandardMaterial({ color: 0x3b3d3c, metalness: 0.6, roughness: 0.7 })
    for (let i = 0; i < 34; i++) {
      const w = 0.15 + rand() * 0.5
      const d = new THREE.Mesh(new THREE.BoxGeometry(w, 0.04 + rand() * 0.06, w * (0.4 + rand())), debrisMat)
      d.position.set((rand() - 0.5) * 52, 0.03, (rand() - 0.5) * 52)
      d.rotation.y = rand() * Math.PI
      d.castShadow = true
      this.scene.add(d)
    }

    // low ground haze
    const hazeMat = new THREE.SpriteMaterial({
      map: smokeTexture(), color: 0x7d8fa3, transparent: true,
      opacity: 0.045, depthWrite: false
    })
    for (let i = 0; i < 9; i++) {
      const s = new THREE.Sprite(hazeMat.clone())
      s.position.set((rand() - 0.5) * 46, 0.6 + rand() * 1.4, (rand() - 0.5) * 46)
      s.scale.set(16 + rand() * 14, 8 + rand() * 6, 1)
      s.material.opacity = 0.03 + rand() * 0.035
      this.scene.add(s)
    }
  }

  _lighting() {
    const hemi = new THREE.HemisphereLight(0x4a5e82, 0x0a0c10, 0.85)
    this.scene.add(hemi)

    const dir = new THREE.DirectionalLight(0xa8c0ee, 2.1)
    dir.position.set(-24, 34, -18)
    dir.castShadow = true
    dir.shadow.mapSize.set(2048, 2048)
    dir.shadow.camera.left = -38
    dir.shadow.camera.right = 38
    dir.shadow.camera.top = 38
    dir.shadow.camera.bottom = -38
    dir.shadow.camera.near = 1
    dir.shadow.camera.far = 90
    dir.shadow.bias = -0.0006
    dir.shadow.normalBias = 0.035
    this.scene.add(dir)
    this.sun = dir

    const fill = new THREE.DirectionalLight(0x2b5d8a, 0.55)
    fill.position.set(30, 12, 24)
    this.scene.add(fill)

    const lampSpots = [
      [-12, 7.2, -8], [12, 7.2, 7], [0, 7.2, 19], [-19, 7.2, 15]
    ]
    const shadeMat = new THREE.MeshStandardMaterial({ color: 0x22262a, metalness: 0.9, roughness: 0.35 })
    const bulbMat = new THREE.MeshStandardMaterial({ color: 0xffe0b0, emissive: 0xffb15a, emissiveIntensity: 4 })
    for (const [x, y, z] of lampSpots) {
      const cable = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.02, 1.8, 6), shadeMat)
      cable.position.set(x, y + 1.1, z)
      this.scene.add(cable)
      const shade = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.62, 0.35, 16, 1, true), shadeMat)
      shade.position.set(x, y + 0.25, z)
      this.scene.add(shade)
      const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.16, 12, 8), bulbMat)
      bulb.position.set(x, y, z)
      this.scene.add(bulb)
      const light = new THREE.PointLight(0xffa352, 42, 20, 2)
      light.position.set(x, y - 0.15, z)
      light.castShadow = false
      this.scene.add(light)
      this.lights.push(light)
      this.flickers.push({ light, bulb, base: 42, phase: Math.random() * 100, speed: 1 + Math.random() * 2 })

      const cone = new THREE.Mesh(
        new THREE.CylinderGeometry(0.3, 3.4, 6.4, 18, 1, true),
        new THREE.MeshBasicMaterial({
          color: 0xffb060, transparent: true, opacity: 0.035,
          blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide
        })
      )
      cone.position.set(x, y - 3.2, z)
      this.scene.add(cone)
    }

    // cool rim lights
    for (const [x, z] of [[-28, -12], [28, 12], [0, -28], [0, 28]]) {
      const l = new THREE.PointLight(0x2b7fae, 16, 15, 2)
      l.position.set(x, 4, z)
      this.scene.add(l)
      this.lights.push(l)
    }

    // ambient orange bounce
    const bounce = new THREE.PointLight(0xff5a14, 20, 26, 2)
    bounce.position.set(0, 1.2, 0)
    this.scene.add(bounce)
    this.bounce = bounce
  }

  _dust() {
    const N = 520
    const pos = new Float32Array(N * 3)
    const seed = new Float32Array(N)
    for (let i = 0; i < N; i++) {
      pos[i * 3] = (Math.random() - 0.5) * 58
      pos[i * 3 + 1] = Math.random() * 8
      pos[i * 3 + 2] = (Math.random() - 0.5) * 58
      seed[i] = Math.random() * 100
    }
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    const mat = new THREE.PointsMaterial({
      size: 0.045, map: glowTexture(), color: 0x9fb6cc, transparent: true,
      opacity: 0.42, depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true
    })
    const points = new THREE.Points(geo, mat)
    points.frustumCulled = false
    this.scene.add(points)
    this.dust = { points, seed, pos }
  }

  _skyline(rand) {
    const winTex = windowTexture()
    const mat = new THREE.MeshStandardMaterial({
      color: 0x1a2028, map: winTex, emissiveMap: winTex,
      emissive: 0x8899bb, emissiveIntensity: 0.9, roughness: 0.9, metalness: 0.1
    })
    const dark = new THREE.MeshStandardMaterial({ color: 0x0b0f14, roughness: 1 })
    for (let i = 0; i < 34; i++) {
      const a = (i / 34) * Math.PI * 2 + rand() * 0.08
      const r = 52 + rand() * 30
      const h = 7 + rand() * 24
      const w = 4 + rand() * 7
      const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, w), rand() > 0.3 ? mat : dark)
      b.position.set(Math.cos(a) * r, h / 2 - 1.5, Math.sin(a) * r)
      b.rotation.y = rand() * Math.PI
      this.scene.add(b)
    }
    // antenna beacons
    for (const [x, z, h] of [[-58, -40, 26], [62, 20, 31], [10, -70, 22]]) {
      const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.2, h, 5), dark)
      mast.position.set(x, h / 2, z)
      this.scene.add(mast)
      const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.22, 6, 6), new THREE.MeshBasicMaterial({ color: 0xff2a2a }))
      bulb.position.set(x, h, z)
      this.scene.add(bulb)
      this.flickers.push({ light: null, bulb, base: 1, phase: Math.random() * 10, speed: 0.7, beacon: true })
    }
  }

  _collider(x, z, w, d, ry, top) {
    const hw = w / 2, hd = d / 2
    const c = Math.abs(Math.cos(ry)), s = Math.abs(Math.sin(ry))
    const ex = hw * c + hd * s
    const ez = hw * s + hd * c
    this.colliders.push({ minX: x - ex, maxX: x + ex, minZ: z - ez, maxZ: z + ez, top })
  }

  lineOfSight(from, to) {
    const dir = new THREE.Vector3().subVectors(to, from)
    const dist = dir.length()
    dir.normalize()
    this.raycaster.set(from, dir)
    this.raycaster.far = dist
    const hits = this.raycaster.intersectObjects(this.solids, false)
    return hits.length === 0
  }

  update(dt, t) {
    this.time = t
    if (this.skyMat) this.skyMat.uniforms.uTime.value = t

    for (const f of this.flickers) {
      if (f.beacon) {
        const on = (Math.sin(t * 2.2 + f.phase) > 0.2) ? 1 : 0.12
        f.bulb.material.color.setRGB(on, on * 0.08, on * 0.08)
        continue
      }
      const n = Math.sin(t * f.speed * 3.1 + f.phase) * 0.5 + Math.sin(t * f.speed * 9.7 + f.phase * 2) * 0.2
      const v = f.base * (0.88 + n * 0.12)
      f.light.intensity = v
      f.bulb.material.emissiveIntensity = 3.2 + n * 0.8
    }

    if (this.beacon) {
      const p = 0.7 + Math.sin(t * 2.4) * 0.25
      this.beacon.material.emissiveIntensity = 2.6 + p * 1.6
      this.beaconBeam.material.opacity = 0.045 + p * 0.03
      this.bounce.intensity = 16 + p * 8
    }

    if (this.dust) {
      const { pos, seed } = this.dust
      for (let i = 0; i < seed.length; i++) {
        const i3 = i * 3
        pos[i3] += Math.sin(t * 0.3 + seed[i]) * dt * 0.25
        pos[i3 + 1] += (0.08 + Math.sin(t * 0.5 + seed[i]) * 0.05) * dt
        pos[i3 + 2] += Math.cos(t * 0.24 + seed[i] * 1.3) * dt * 0.2
        if (pos[i3 + 1] > 8) pos[i3 + 1] = 0.2
        if (pos[i3] > 29) pos[i3] = -29
        if (pos[i3] < -29) pos[i3] = 29
        if (pos[i3 + 2] > 29) pos[i3 + 2] = -29
        if (pos[i3 + 2] < -29) pos[i3 + 2] = 29
      }
      this.dust.points.geometry.attributes.position.needsUpdate = true
    }
  }
}

import * as THREE from 'three'
import { sparkTexture, smokeTexture, bulletHoleTexture, glowTexture } from './textures.js'

const _v = new THREE.Vector3()
const _q = new THREE.Quaternion()

export class Effects {
  constructor(scene) {
    this.scene = scene
    this.time = 0

    // ---- sparks ----
    this.sparkCount = 900
    this.sparkPos = new Float32Array(this.sparkCount * 3)
    this.sparkCol = new Float32Array(this.sparkCount * 3)
    this.sparkVel = new Float32Array(this.sparkCount * 3)
    this.sparkLife = new Float32Array(this.sparkCount)
    this.sparkMax = new Float32Array(this.sparkCount)
    this.sparkCursor = 0
    const sg = new THREE.BufferGeometry()
    sg.setAttribute('position', new THREE.BufferAttribute(this.sparkPos, 3))
    sg.setAttribute('color', new THREE.BufferAttribute(this.sparkCol, 3))
    const sm = new THREE.PointsMaterial({
      size: 0.085, map: sparkTexture(), vertexColors: true, transparent: true,
      opacity: 1, depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true
    })
    this.sparks = new THREE.Points(sg, sm)
    this.sparks.frustumCulled = false
    this.sparks.renderOrder = 3
    this.scene.add(this.sparks)
    for (let i = 0; i < this.sparkCount; i++) this.sparkPos[i * 3 + 1] = -999

    // ---- smoke ----
    this.smokePool = []
    this.smokeCursor = 0
    for (let i = 0; i < 30; i++) {
      const s = new THREE.Sprite(new THREE.SpriteMaterial({
        map: smokeTexture(), transparent: true, opacity: 0, depthWrite: false, color: 0x8d949e
      }))
      s.visible = false
      s.userData = { life: 0, max: 1, vel: new THREE.Vector3(), grow: 1 }
      this.scene.add(s)
      this.smokePool.push(s)
    }

    // ---- tracers ----
    this.tracerPool = []
    this.tracerCursor = 0
    const tg = new THREE.BoxGeometry(1, 1, 1)
    for (let i = 0; i < 26; i++) {
      const m = new THREE.Mesh(tg, new THREE.MeshBasicMaterial({
        color: 0xffc070, transparent: true, opacity: 0, blending: THREE.AdditiveBlending,
        depthWrite: false, fog: false
      }))
      m.visible = false
      m.userData = { life: 0, max: 0.1 }
      this.scene.add(m)
      this.tracerPool.push(m)
    }

    // ---- decals ----
    this.decalPool = []
    this.decalCursor = 0
    const dg = new THREE.PlaneGeometry(0.16, 0.16)
    for (let i = 0; i < 64; i++) {
      const m = new THREE.Mesh(dg, new THREE.MeshBasicMaterial({
        map: bulletHoleTexture(), transparent: true, opacity: 0.9,
        depthWrite: false, polygonOffset: true, polygonOffsetFactor: -4
      }))
      m.visible = false
      this.scene.add(m)
      this.decalPool.push(m)
    }

    // ---- shells ----
    this.shellPool = []
    this.shellCursor = 0
    const shg = new THREE.CylinderGeometry(0.018, 0.018, 0.06, 8)
    const shm = new THREE.MeshStandardMaterial({ color: 0xd9a441, metalness: 1, roughness: 0.3 })
    for (let i = 0; i < 24; i++) {
      const m = new THREE.Mesh(shg, shm)
      m.visible = false
      m.castShadow = false
      m.userData = { life: 0, vel: new THREE.Vector3(), spin: new THREE.Vector3(), grounded: false }
      this.scene.add(m)
      this.shellPool.push(m)
    }

    // ---- explosions ----
    this.explosions = []
    const eg = new THREE.IcosahedronGeometry(1, 2)
    this.explosionGeo = eg
    this.ringGeo = new THREE.RingGeometry(0.9, 1, 40)
    this.flashLight = new THREE.PointLight(0xffa040, 0, 22, 2)
    this.scene.add(this.flashLight)
    this.flashLife = 0
    this.flashMax = 0.12
    this.flashBase = 0

    // muzzle glow sprite
    this.muzzleSprite = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTexture('rgba(255,255,235,1)', 'rgba(255,170,70,0.7)'),
      transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false
    }))
    this.muzzleSprite.scale.set(1.1, 1.1, 1)
    this.scene.add(this.muzzleSprite)

    // dust motes for impacts
    this.impactSprite = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTexture('rgba(255,230,190,0.9)', 'rgba(255,150,50,0.5)'),
      transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false
    }))
    this.scene.add(this.impactSprite)
  }

  _nextSpark() {
    const i = this.sparkCursor
    this.sparkCursor = (this.sparkCursor + 1) % this.sparkCount
    return i
  }

  sparks(origin, normal, count = 12, color = 0xffb060, speed = 6) {
    const c = new THREE.Color(color)
    for (let k = 0; k < count; k++) {
      const i = this._nextSpark()
      const i3 = i * 3
      this.sparkPos[i3] = origin.x + (Math.random() - 0.5) * 0.08
      this.sparkPos[i3 + 1] = origin.y + (Math.random() - 0.5) * 0.08
      this.sparkPos[i3 + 2] = origin.z + (Math.random() - 0.5) * 0.08
      const sp = speed * (0.35 + Math.random() * 0.9)
      _v.set(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5).normalize()
        .multiplyScalar(sp)
      if (normal) _v.addScaledVector(normal, sp * 0.9)
      this.sparkVel[i3] = _v.x
      this.sparkVel[i3 + 1] = _v.y + 1.2
      this.sparkVel[i3 + 2] = _v.z
      const tint = 0.75 + Math.random() * 0.25
      this.sparkCol[i3] = c.r * tint
      this.sparkCol[i3 + 1] = c.g * tint
      this.sparkCol[i3 + 2] = c.b * tint
      this.sparkLife[i] = this.sparkMax[i] = 0.25 + Math.random() * 0.55
    }
  }

  smoke(origin, count = 1, color = 0x8d949e, scale = 1) {
    for (let k = 0; k < count; k++) {
      const s = this.smokePool[this.smokeCursor]
      this.smokeCursor = (this.smokeCursor + 1) % this.smokePool.length
      s.visible = true
      s.position.copy(origin).add(_v.set((Math.random() - 0.5) * 0.2, Math.random() * 0.15, (Math.random() - 0.5) * 0.2))
      s.material.color.setHex(color)
      s.material.opacity = 0.35 + Math.random() * 0.2
      const sz = (0.5 + Math.random() * 0.5) * scale
      s.scale.set(sz, sz, 1)
      s.userData.life = s.userData.max = 0.9 + Math.random() * 1.1
      s.userData.vel.set((Math.random() - 0.5) * 0.3, 0.25 + Math.random() * 0.3, (Math.random() - 0.5) * 0.3)
      s.userData.grow = 1.6 + Math.random() * 1.8
      s.userData.baseScale = sz
    }
  }

  tracer(from, to, color = 0xffc070, width = 0.028, life = 0.075) {
    const m = this.tracerPool[this.tracerCursor]
    this.tracerCursor = (this.tracerCursor + 1) % this.tracerPool.length
    const dist = from.distanceTo(to)
    if (dist < 0.01) return
    m.visible = true
    m.position.copy(from).lerp(to, 0.5)
    m.lookAt(to)
    m.scale.set(width, width, dist)
    m.material.color.setHex(color)
    m.material.opacity = 0.95
    m.userData.life = m.userData.max = life
  }

  decal(point, normal) {
    const m = this.decalPool[this.decalCursor]
    this.decalCursor = (this.decalCursor + 1) % this.decalPool.length
    m.visible = true
    m.position.copy(point).addScaledVector(normal, 0.008)
    _v.copy(point).add(normal)
    m.lookAt(_v)
    const s = 0.7 + Math.random() * 0.7
    m.scale.set(s, s, 1)
    m.rotation.z = Math.random() * Math.PI * 2
  }

  impact(point, normal, kind = 'metal') {
    const col = kind === 'metal' ? 0xffc070 : 0xd9c9a8
    this.sparks(point, normal, kind === 'metal' ? 14 : 8, col, 6)
    this.smoke(point, 1, kind === 'metal' ? 0x7d838c : 0x8a8171, 0.7)
    this.decal(point, normal)
    this.impactSprite.position.copy(point).addScaledVector(normal, 0.05)
    this.impactSprite.material.opacity = 0.9
    this.impactSprite.scale.set(0.5, 0.5, 1)
  }

  shell(position, direction) {
    const m = this.shellPool[this.shellCursor]
    this.shellCursor = (this.shellCursor + 1) % this.shellPool.length
    m.visible = true
    m.position.copy(position)
    m.rotation.set(Math.random() * 6, Math.random() * 6, Math.random() * 6)
    const d = m.userData
    d.vel.copy(direction).multiplyScalar(1.4 + Math.random())
    d.vel.y += 1.6 + Math.random()
    d.vel.x += (Math.random() - 0.5) * 1.2
    d.vel.z += (Math.random() - 0.5) * 1.2
    d.spin.set(Math.random() * 14, Math.random() * 14, Math.random() * 14)
    d.life = 3
    d.grounded = false
  }

  muzzle(position, color = 0xffb060) {
    this.muzzleSprite.position.copy(position)
    this.muzzleSprite.material.color.setHex(color)
    this.muzzleSprite.material.opacity = 0.95
    this.muzzleSprite.scale.setScalar(0.8 + Math.random() * 0.5)
    this.flashLight.position.copy(position)
    this.flashLight.color.setHex(color)
    this.flashBase = 45
    this.flashLight.intensity = this.flashBase
    this.flashLife = this.flashMax = 0.07
  }

  explosion(point, scale = 1) {
    const mesh = new THREE.Mesh(this.explosionGeo, new THREE.MeshBasicMaterial({
      color: 0xffa040, transparent: true, opacity: 0.95,
      blending: THREE.AdditiveBlending, depthWrite: false
    }))
    mesh.position.copy(point)
    mesh.scale.setScalar(0.4 * scale)
    this.scene.add(mesh)
    const ring = new THREE.Mesh(this.ringGeo, new THREE.MeshBasicMaterial({
      color: 0xffc070, transparent: true, opacity: 0.9,
      blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide
    }))
    ring.position.copy(point)
    ring.position.y = 0.05
    ring.rotation.x = -Math.PI / 2
    ring.scale.setScalar(0.5 * scale)
    this.scene.add(ring)
    this.explosions.push({ mesh, ring, life: 0, max: 0.55, scale })
    this.sparks(point, new THREE.Vector3(0, 1, 0), 50 * scale, 0xffa040, 14 * scale)
    this.smoke(point, 6, 0x6d6a66, 3 * scale)
    this.flashLight.position.copy(point)
    this.flashLight.color.setHex(0xff8a30)
    this.flashBase = 160 * scale
    this.flashLight.intensity = this.flashBase
    this.flashLife = this.flashMax = 0.22
  }

  update(dt) {
    this.time += dt

    // sparks
    for (let i = 0; i < this.sparkCount; i++) {
      if (this.sparkLife[i] <= 0) continue
      this.sparkLife[i] -= dt
      const i3 = i * 3
      if (this.sparkLife[i] <= 0) {
        this.sparkCol[i3] = this.sparkCol[i3 + 1] = this.sparkCol[i3 + 2] = 0
        this.sparkPos[i3 + 1] = -999
        continue
      }
      this.sparkVel[i3 + 1] -= 13 * dt
      this.sparkPos[i3] += this.sparkVel[i3] * dt
      this.sparkPos[i3 + 1] += this.sparkVel[i3 + 1] * dt
      this.sparkPos[i3 + 2] += this.sparkVel[i3 + 2] * dt
      if (this.sparkPos[i3 + 1] < 0.02) {
        this.sparkPos[i3 + 1] = 0.02
        this.sparkVel[i3 + 1] *= -0.3
        this.sparkVel[i3] *= 0.7
        this.sparkVel[i3 + 2] *= 0.7
      }
      const f = this.sparkLife[i] / this.sparkMax[i]
      const s = f * f
      this.sparkCol[i3] *= 1
      // fade via scaling color relative to spawn is expensive; use decay
      this.sparkCol[i3] = Math.min(this.sparkCol[i3], 1) * (0.985 - dt * 2)
      this.sparkCol[i3 + 1] *= 0.985 - dt * 2
      this.sparkCol[i3 + 2] *= 0.985 - dt * 2
      if (s < 0.01) {
        this.sparkCol[i3] = this.sparkCol[i3 + 1] = this.sparkCol[i3 + 2] = 0
      }
    }
    this.sparks.geometry.attributes.position.needsUpdate = true
    this.sparks.geometry.attributes.color.needsUpdate = true

    // smoke
    for (const s of this.smokePool) {
      if (!s.visible) continue
      const d = s.userData
      d.life -= dt
      if (d.life <= 0) { s.visible = false; continue }
      s.position.addScaledVector(d.vel, dt)
      d.vel.multiplyScalar(1 - dt * 0.6)
      const f = d.life / d.max
      s.material.opacity = 0.35 * f
      const sc = d.baseScale * (1 + (1 - f) * d.grow)
      s.scale.set(sc, sc, 1)
    }

    // tracers
    for (const m of this.tracerPool) {
      if (!m.visible) continue
      m.userData.life -= dt
      if (m.userData.life <= 0) { m.visible = false; continue }
      m.material.opacity = 0.95 * (m.userData.life / m.userData.max)
    }

    // shells
    for (const m of this.shellPool) {
      if (!m.visible) continue
      const d = m.userData
      d.life -= dt
      if (d.life <= 0) { m.visible = false; continue }
      if (!d.grounded) {
        d.vel.y -= 16 * dt
        m.position.addScaledVector(d.vel, dt)
        m.rotation.x += d.spin.x * dt
        m.rotation.y += d.spin.y * dt
        m.rotation.z += d.spin.z * dt
        if (m.position.y < 0.03) {
          m.position.y = 0.03
          d.vel.y *= -0.35
          d.vel.x *= 0.6
          d.vel.z *= 0.6
          d.spin.multiplyScalar(0.5)
          if (Math.abs(d.vel.y) < 0.4) d.grounded = true
        }
      }
    }

    // explosions
    for (let i = this.explosions.length - 1; i >= 0; i--) {
      const e = this.explosions[i]
      e.life += dt
      const f = e.life / e.max
      if (f >= 1) {
        this.scene.remove(e.mesh)
        this.scene.remove(e.ring)
        e.mesh.material.dispose()
        e.ring.material.dispose()
        this.explosions.splice(i, 1)
        continue
      }
      const s = e.scale * (0.4 + f * 3.2)
      e.mesh.scale.setScalar(s)
      e.mesh.material.opacity = (1 - f) * 0.9
      e.ring.scale.setScalar(e.scale * (0.6 + f * 7))
      e.ring.material.opacity = (1 - f) * 0.7
    }

    // muzzle / impact glows
    if (this.muzzleSprite.material.opacity > 0) {
      this.muzzleSprite.material.opacity = Math.max(0, this.muzzleSprite.material.opacity - dt * 18)
    }
    if (this.impactSprite.material.opacity > 0) {
      this.impactSprite.material.opacity = Math.max(0, this.impactSprite.material.opacity - dt * 7)
    }

    if (this.flashLife > 0) {
      this.flashLife -= dt
      const f = Math.max(0, this.flashLife / this.flashMax)
      this.flashLight.intensity = this.flashBase * f * f
    } else {
      this.flashLight.intensity = 0
    }
  }

  reset() {
    for (const m of this.tracerPool) m.visible = false
    for (const m of this.decalPool) m.visible = false
    for (const m of this.shellPool) m.visible = false
    for (const s of this.smokePool) s.visible = false
    for (let i = 0; i < this.sparkCount; i++) {
      this.sparkLife[i] = 0
      this.sparkPos[i * 3 + 1] = -999
      this.sparkCol[i * 3] = this.sparkCol[i * 3 + 1] = this.sparkCol[i * 3 + 2] = 0
    }
    this.sparks.geometry.attributes.position.needsUpdate = true
    this.sparks.geometry.attributes.color.needsUpdate = true
    for (const e of this.explosions) {
      this.scene.remove(e.mesh); this.scene.remove(e.ring)
    }
    this.explosions.length = 0
    this.muzzleSprite.material.opacity = 0
    this.impactSprite.material.opacity = 0
    this.flashLight.intensity = 0
  }
}

